// Command gen writes store/pgadapter_gen.go: a type that satisfies
// sqlitedb.Querier by calling pgdb.Queries. Both packages are generated by
// sqlc from the same queries over schemas with identical column types, so
// every struct converts directly; the generator fails if they ever differ.
package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"log"
	"os"
	"sort"
	"strings"
)

func main() {
	pg := methods("pgdb/querier.go")
	lite := methods("sqlitedb/querier.go")
	if len(pg) != len(lite) {
		log.Fatalf("pgdb has %d queries, sqlitedb has %d", len(pg), len(lite))
	}

	names := make([]string, 0, len(pg))
	for name := range pg {
		names = append(names, name)
	}
	sort.Strings(names)

	var methods bytes.Buffer
	for _, name := range names {
		m, other := pg[name], lite[name]
		if sig(m) != sig(other) {
			log.Fatalf("%s differs between dialects:\n  pgdb:     %s\n  sqlitedb: %s", name, sig(m), sig(other))
		}
		writeMethod(&methods, name, m)
	}
	// A query that takes a bare time or nullable value names its package.
	std := `"context"`
	for _, pkg := range []string{"database/sql", "time"} {
		if bytes.Contains(methods.Bytes(), []byte(" "+pkg[strings.LastIndex(pkg, "/")+1:]+".")) {
			std += "\n\t\"" + pkg + "\""
		}
	}

	var b bytes.Buffer
	b.WriteString(`// Code generated by store/gen from pgdb/querier.go. DO NOT EDIT.

package store

import (
	` + std + `

	"github.com/locodarwin/mila/server/internal/store/pgdb"
	"github.com/locodarwin/mila/server/internal/store/sqlitedb"
)

// pgQueries presents the Postgres queries through the SQLite package's
// types, so the rest of the server sees one set of types.
type pgQueries struct{ q *pgdb.Queries }

var _ sqlitedb.Querier = pgQueries{}
`)
	b.Write(methods.Bytes())

	out, err := format.Source(b.Bytes())
	if err != nil {
		log.Fatalf("format: %v\n%s", err, b.String())
	}
	if err := os.WriteFile("pgadapter_gen.go", out, 0o644); err != nil {
		log.Fatal(err)
	}
}

func methods(path string) map[string]*ast.FuncType {
	f, err := parser.ParseFile(token.NewFileSet(), path, nil, 0)
	if err != nil {
		log.Fatal(err)
	}
	found := map[string]*ast.FuncType{}
	ast.Inspect(f, func(n ast.Node) bool {
		ts, ok := n.(*ast.TypeSpec)
		if !ok || ts.Name.Name != "Querier" {
			return true
		}
		for _, field := range ts.Type.(*ast.InterfaceType).Methods.List {
			found[field.Names[0].Name] = field.Type.(*ast.FuncType)
		}
		return false
	})
	if len(found) == 0 {
		log.Fatalf("%s: no Querier interface", path)
	}
	return found
}

// sig renders a signature for comparison between the two packages.
func sig(ft *ast.FuncType) string {
	var parts []string
	for _, p := range ft.Params.List {
		parts = append(parts, expr(p.Type, ""))
	}
	parts = append(parts, "->")
	for _, r := range ft.Results.List {
		parts = append(parts, expr(r.Type, ""))
	}
	return strings.Join(parts, " ")
}

// expr prints a type, qualifying the package's own (exported) types.
func expr(e ast.Expr, pkg string) string {
	switch t := e.(type) {
	case *ast.Ident:
		if pkg != "" && ast.IsExported(t.Name) {
			return pkg + "." + t.Name
		}
		return t.Name
	case *ast.SelectorExpr:
		return t.X.(*ast.Ident).Name + "." + t.Sel.Name
	case *ast.ArrayType:
		return "[]" + expr(t.Elt, pkg)
	}
	log.Fatalf("unsupported type %T", e)
	return ""
}

func isLocal(e ast.Expr) bool {
	id, ok := e.(*ast.Ident)
	return ok && ast.IsExported(id.Name)
}

func writeMethod(b *bytes.Buffer, name string, ft *ast.FuncType) {
	var params, args []string
	for i, p := range ft.Params.List {
		pname := fmt.Sprintf("a%d", i)
		if len(p.Names) > 0 {
			pname = p.Names[0].Name
		}
		params = append(params, pname+" "+expr(p.Type, "sqlitedb"))
		if isLocal(p.Type) {
			args = append(args, "pgdb."+expr(p.Type, "")+"("+pname+")")
		} else {
			args = append(args, pname)
		}
	}
	var results []string
	for _, r := range ft.Results.List {
		results = append(results, expr(r.Type, "sqlitedb"))
	}
	call := fmt.Sprintf("p.q.%s(%s)", name, strings.Join(args, ", "))
	fmt.Fprintf(b, "\nfunc (p pgQueries) %s(%s) (%s) {\n", name, strings.Join(params, ", "), strings.Join(results, ", "))

	if len(ft.Results.List) == 1 { // error only
		fmt.Fprintf(b, "\treturn %s\n}\n", call)
		return
	}
	res := ft.Results.List[0].Type
	switch {
	case isLocal(res):
		fmt.Fprintf(b, "\tv, err := %s\n\treturn sqlitedb.%s(v), err\n}\n", call, expr(res, ""))
	case isSliceOfLocal(res):
		elt := expr(res.(*ast.ArrayType).Elt, "")
		fmt.Fprintf(b, "\tv, err := %s\n\tout := make([]sqlitedb.%s, len(v))\n\tfor i := range v {\n\t\tout[i] = sqlitedb.%s(v[i])\n\t}\n\treturn out, err\n}\n", call, elt, elt)
	default:
		fmt.Fprintf(b, "\treturn %s\n}\n", call)
	}
}

func isSliceOfLocal(e ast.Expr) bool {
	a, ok := e.(*ast.ArrayType)
	return ok && isLocal(a.Elt)
}
